from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    row_lines = [
        r for r in range(h)
        if len(set(grid[r])) == 1 and grid[r][0] != background
    ]
    col_lines = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1
        and grid[0][c] != background
    ]
    divider_colors = {grid[r][0] for r in row_lines}
    divider_colors.update(grid[0][c] for c in col_lines)

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or color in divider_colors:
                continue

            seen = {(r, c)}
            queue = deque([(r, c)])
            while queue:
                y, x = queue.popleft()
                for axis in row_lines:
                    ny, nx = 2 * axis - y, x
                    if 0 <= ny < h and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        queue.append((ny, nx))
                for axis in col_lines:
                    ny, nx = y, 2 * axis - x
                    if 0 <= nx < w and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        queue.append((ny, nx))

            for y, x in seen:
                out[y][x] = color

    return out
